mapper.select:
/* selectMasterMdCdAgentCardInfoPopVisit */ SELECT AGENT , BUYER , (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = KAV.BUYER) AS BUYER_NAME_LOC , TO_CHAR(TO_DATE(KAV.VISIT_DATE || KAV.VISIT_TIME,'YYYYMMDDHH24MISS'), 'YYYY-MM-DD HH24:MI') AS CSTMR_VISIT_DATE , (SELECT COD.TEXT1 FROM ICOMCOD1 COD WHERE COD.TYPE ='K006' AND COD.CODE = KAV.VISIT_TYPE) AS VISIT_TYPE , (SELECT A.USER_NAME_LOC FROM ICOMLUSR A WHERE A.USER_ID = KAV.ADD_USER_ID ) AS USER_NAME_LOC , SUBSTR(KAV.VISIT_NOTE,0,50) AS VISIT_NOTE , DECODE(KAV.IMAGE_KEY, NULL, '0', '1') AS IMAGE_FLAG , KAV.IMAGE_KEY , KAV.ADD_DATE , KAV.ADD_TIME , KAV.ADD_USER_ID FROM KEP_AGENT_VISIT KAV WHERE 1=1 AND KAV.AGENT = #{com_code} AND KAV.STATUS <> 'D'
AND KAV.AGENT = 'KRKEPS0002' AND (KAV.VISIT_NOTE LIKE '%' || #{st_agent_name} || '%' OR KAV.AGENT_NAME LIKE '%' || #{st_agent_name} || '%')
ORDER BY KAV.VISIT_DATE DESC

mapper.update:

UPDATE KEP_AGENT_VISIT A
SET A.STATUS = 'D'
WHERE A.AGENT = #{AGENT}
AND A.ADD_DATE = #{ADD_DATE}
AND A.ADD_TIME = #{ADD_TIME}
AND A.STATUS <> 'D'
